mapper.select:
SELECT pr.id AS id, pr.order_no AS orderNo, pr.purchase_order_id AS purchaseOrderId, po.order_no AS purchaseOrderNo, pr.supplier_id AS supplierId, s.name AS supplierName, pr.status AS status, pr.return_reason AS returnReason, pr.total_amount AS totalAmount, pr.create_by AS createBy, pr.create_time AS createTime, pr.audit_by AS auditBy, pr.audit_time AS auditTime, pr.audit_remark AS auditRemark, pr.remark AS remark FROM purchase_return_order pr JOIN purchase_order po ON po.id = pr.purchase_order_id JOIN supplier s ON s.id = pr.supplier_id
AND pr.order_no LIKE CONCAT('%', #{q.orderNo}, '%')
AND po.order_no LIKE CONCAT('%', #{q.purchaseOrderNo}, '%')
AND pr.supplier_id = #{q.supplierId}
AND pr.status = #{q.status}
AND pr.create_time >= #{beginTime}
AND pr.create_time < #{endTime}
ORDER BY pr.id DESC
